INSERT INTO messages VALUES (56158,'false_120363330794869864@g.us_ACD9152B54E03C5286AAFD8DD061BA42_249001265856521@lid','120363330794869864@g.us','Cowwnhecimento 🐮📚','249001265856521@lid','Desconhecido','The webinar *“The Impact of Quantum Technologies on Industry in Latin America”* takes place *tomorrow*.\n\nThe session will discuss how quantum technologies are beginning to influence industrial strategy, innovation ecosystems, and technology development across the region.\n\nSpeaker: Matías Bilkis\n June 10th\n🕖 7:00 PM (BRT)\n💻 Online\n\nLast spots available: https://doity.com.br/quiin-expert-talks-the-impact-of-quantum-technologies-on-industry-in-latin-america',0,'image',1781033121,'2026-06-11T14:52:12.195604',NULL,NULL,NULL,NULL);
