INSERT INTO messages VALUES (56155,'false_120363330794869864@g.us_AC949F842A8C5E6B6AC3383E8FD3BB98_173753371766785@lid','120363330794869864@g.us','Cowwnhecimento 🐮📚','173753371766785@lid','Desconhecido','🚨 ENQUANTO VOCÊ AINDA TEM MEDO DO MERCADO CRIPTO... Os jovens da ETEC de Diadema já estão dando os primeiros passos para as suas carreiras Web3! 🎓💻\n\nA CSG Academy esteve presente na ETEC e o resultado foi SURPREENDENTE!\nLink: https://www.instagram.com/p/DZXnOtMjq8g/?igsh=MWF6ZmMxZHZlMG1xNA==\n\n🔥 O QUE ELES APRENDERAM NA PRÁTICA?\n\n✅ Blockchain – como funciona e por que veio pra ficar!!\n✅ Carteiras digitais – e eles criaram as suas na hora!\n✅ NFTs – muito além das artes caras.\n✅ Jogos NFT – como jogar e ganhar ao mesmo tempo.\n✅ Segurança básica para não cair em golpes.\n\n💡 E O MELHOR:\n\nEles não tiveram medo de perguntar. Não tiveram medo de aprender. Não tiveram medo de dar o primeiro passo.\nEnquanto esses jovens já estão criando carteiras e se preparando para oportunidades reais no mercado cripto... Você ainda está esperando o "momento certo"? 🤔\n\nO mercado não espera. E a nova geração já está na frente!!!\n\n🚀 Quer levar esse aprendizado para sua instituição ou empresa?\nChama a gente no direct ou no WhatsApp!\n📩 https://api.whatsapp.com/send?phone=5511919193752\n\n✏️ CSG ACADEMY – transformando conhecimento em liberdade financeira 💎',0,'chat',1781047242,'2026-06-11T14:52:12.181819',NULL,NULL,NULL,NULL);
INSERT INTO messages VALUES (56154,'false_120363330794869864@g.us_3EB01386AA1B87DDFA5985_20203660402840@lid','120363330794869864@g.us','Cowwnhecimento 🐮📚','20203660402840@lid','Desconhecido','GFT Brasil - Fundamentos de Cloud com AWSDomine os fundamentos de cloud na AWS para atuar como Cloud Solution Architect em projetos reais com a GFT Brasil. Construa uma base sólida em computação, redes, segurança, bancos de dados e DevOps na nuvem, em uma trilha intensiva com 11 módulos práticos em AWS Garanta sua vaga e acelere sua carreira em tecnologia.  https://www.dio.me/bootcamp/gft-fundamentos-de-cloud-com-aws',0,'chat',1781056197,'2026-06-11T14:52:12.178666',NULL,NULL,NULL,NULL);
INSERT INTO messages VALUES (56153,'false_120363330794869864@g.us_3EB005BEB9A6392C85CF50_20203660402840@lid','120363330794869864@g.us','Cowwnhecimento 🐮📚','20203660402840@lid','Desconhecido','Bolsa Santander\nSantander Apoio Financeiro Universitário 2026 São 2.000 bolsas de R$ 3.000 para alunos de graduação e pós-graduação de universidades conveniadas em todo o Brasil. Transforme seu futuro com o Santander Apoio Financeiro Universitário 2026! 🎓 São 2.000 bolsas de R$ 3.000 para alunos de graduação e pós-graduação de universidades conveniadas em todo o Brasil. Utilize o auxílio para mensalidades, rematrícula, transporte, alimentação e materiais didáticos. Desde 2017, mais de 9.300 alunos já foram beneficiados. Inscreva-se agora e não perca essa oportunidade! São elegíveis:\n\nEstudantes de graduação e pós-graduação\nMaiores de 18 anos no momento da inscrição\nMatriculados em universidades conveniadas na modalidade presencial ou a distância (EAD)\nNão são elegíveis:\n\nQuem já foi contemplado em outros programas de apoio financeiro do Santander.\nFuncionários, executivos, estagiários e jovens aprendizes do Grupo Santander (coligadas).\nFuncionários, executivos, estagiários, jovens aprendizes, professores, gestores e coordenadores das universidades conveniadas, bem como seus familiares, cônjuges e parentes.\nOutras informações importantes:\n\nCada candidato selecionado terá direito a apenas uma bolsa.\nAs universidades não podem exigir que os candidatos realizem atividades específicas, como estágios, ou estabelecer vínculos e condições não previstos nos termos do programa.\nA seleção dos candidatos será feita exclusivamente pelas universidades conveniadas, seguindo os critérios estabelecidos nos editais e nos princípios gerais do programa, sem interferência do Santander. https://app.santanderopenacademy.com/pt-BR/program/santander-apoio-financeiro-universitario-2026?utm_content=11ff14d7-a2e8-4e3d-96a4-a5419010dcef%7CSoaTop10RankingPlacement%7Cdps:offer-placement:19df2f21fe0b5c09%7CSoaTop10Ranking%7Cdps:personalized-offer:1ca5e0a72cb3298f',0,'chat',1781056436,'2026-06-11T14:52:12.175847',NULL,NULL,NULL,NULL);
INSERT INTO messages VALUES (56152,'false_120363330794869864@g.us_AC928FF79977618297F6820D79167F8D_20203660402840@lid','120363330794869864@g.us','Cowwnhecimento 🐮📚','20203660402840@lid','Desconhecido','Curso Santander\nBootcamp Universia - Primeiros Passos em Power BI\n\n _Informações gerais do curso_\n\nCurso gratuito de Power BI: a Universia abre 10 mil bolsas para quem quer aprender Power BI, SQL, DAX e IA Generativa na prática.\n\n Do zero a um dashboard gerencial real de portfólio, com mentoria ao vivo e certificado. Inscreva-se e concorra à sua bolsa! O programa é aberto a todos os interessados, independente de experiência anterior ou região do Brasil. A trilha é indicada para estudantes, iniciantes e profissionais em transição de carreira que queiram aprender Power BI e Inteligência Artificial na prática. Não é necessário ser cliente Santander para participar. Os participantes terão suporte durante todo o programa pelo e-mail santander@dio.me.\n\n Saiba mais em: https://app.santanderopenacademy.com/pt-BR/program/bootcamp-universia-2026?utm_content=13b55151-8fba-4e59-9df8-1611ff1516f1%7CSoaTop10RankingPlacement%7Cdps:offer-placement:19df2f21fe0b5c09%7CSoaTop10Ranking%7Cdps:personalized-offer:1ca496969a732855',0,'chat',1781056528,'2026-06-11T14:52:12.170355',NULL,NULL,NULL,NULL);
