INSERT INTO messages VALUES (56147,'true_120363330794869864@g.us_4074538505_553171319392@c.us','120363330794869864@g.us','Cowwnhecimento 🐮📚','553171319392@c.us','Equipe','https://chat.whatsapp.com/Gba7JUJgrqz2lg2PqVlE6T\n\n*REGRAS DO COWWNCHECIMENTO:*\n\n🚨PROIBIDO ANÚNCIOS SEM AUTORIZAÇÃO DA ADMINISTRAÇÃO 🚨\nUm anúncio é uma peça de comunicação persuasiva, escrita ou visual, criada para promover produtos, serviços, marcas ou ideias a um público-alvo. (Nos ajude, que te ajudamos)\n\n🏆 DIVULGAÇÕES DE MARATONAS OU DESAFIOS SIMILARES SÃO EXCLUSIVOS PARA PARCEIROS E PATROCINADORES. ENTREM EM CONTATO PARA SABER MAIS 🏆\nApagaremos TODAS as mensagens fora do padrão sem aviso prévio. \n\nTipo de Conteúdo Permitido no COWWNHECIMENTO:\n- Links para cursos online, workshops e seminários.\n- Bootcamp (haverá avaliação)\n- Bolsas de estudo\n- Mentorias\n- Artigos, tutoriais e recursos educacionais.\n💰Cobramos comissionamento caso haja cobrança de inscrição\n\nRegras de Postagem:\n- Relevância: Certifique-se de que o conteúdo compartilhado esteja alinhado com o objetivo do grupo.\n- Qualidade: Verifique a validade e a qualidade dos links antes de compartilhar.\n- Descrição: Ao compartilhar um link, inclua uma breve descrição sobre o que se trata e por que é relevante.\n- Periodicidade: Evite postar o mesmo conteúdo repetidamente. Espere um período razoável entre postagens semelhantes.\n\nInterações e Comportamento:\n- Respeito: Mantenha um tom respeitoso e construtivo nas interações. Comentários ofensivos ou desrespeitosos não serão tolerados.\n- Ajuda Mútua: Se alguém tiver dúvidas ou precisar de mais informações, sinta-se à vontade para ajudar de maneira colaborativa.\n- Feedback: Sugestões e feedback construtivo sobre o grupo são bem-vindos, desde que respeitosos e relevantes.',1,'gp2',1781142572,'2026-06-11T14:52:12.145765','553171319392',NULL,NULL,NULL);
