INSERT INTO messages VALUES (56435,'false_120363413324066064@g.us_3A04868BA44F1CF5C75C_229536692199679@lid','120363413324066064@g.us','VAGAS TECNOLOGIA V','229536692199679@lid','Desconhecido','*🚀🔥 PESSOAL, PRECISO DA OPINIÃO DE VOCÊS! 🔥🚀*\n\n*Estou pensando em realizar um Workshop de Carreira em Tecnologia voltado para quem está começando na área, em transição de carreira ou ainda tentando encontrar um caminho dentro do mercado de tecnologia.*\n\n*A ideia é trazer um Diretor de Desenvolvimento de uma multinacional austríaca, profissional com mais de 17 anos de experiência, para compartilhar sua visão, trajetória e experiências reais do mercado.*\n\n*📌 Para viabilizar o evento, seria cobrado apenas um valor simbólico de participação.*\n\n*Antes de organizar tudo, gostaria de entender o interesse da comunidade.*\n\n*👀 Você participaria de um evento como esse?*\n\n*Comente “EU PARTICIPARIA” ou deixe um 🔥 nos comentários.*\n\n*Dependendo da quantidade de interessados, vou avançar com a organização e divulgar mais detalhes em breve. 🚀💻*',0,'chat',1781145324,'2026-06-11T14:52:45.514124',NULL,NULL,NULL,NULL);
