INSERT INTO messages VALUES (56450,'false_120363304055240101@g.us_AC9796E89A792D6335BFD52FCB1BCF67_20203660402840@lid','120363304055240101@g.us','Montar Times CowwPeões 🐮🫂','20203660402840@lid','Desconhecido','🚀 *Santander X Award 2026 | Do Brasil para o mundo!*\n\nEstão abertas as inscrições para uma das principais premiações de inovação e empreendedorismo do país! 🌎\n\nPodem participar:\n\n✅ Pequenas e Médias Empresas\n✅ Startups e Scaleups\n✅ Projetos Universitários\n\n💰 São mais de R$ 600 mil em premiações\n🎓 Aceleração, benefícios e mentorias\n🌍 Visibilidade e conexão internacional\n\n📅 Inscrições até 16/08\n\n🔗*Inscrições 👇🏻*\n\n*PMEs*\nhttps://app.santanderx.com/calls/santander-x-brazil-award-pmes-2026?utm_source=Whatsapp&utm_medium=Laminawhats&utm_campaign=SXBR-WhatsappAward\n\n*Startups e Scaleups*\nhttps://app.santanderx.com/calls/santander-x-brazil-award-startup-e-scaleup-2026?utm_source=Whatsapp&utm_medium=Laminawhats&utm_campaign=SXBR-WhatsappAward\n\n*Projetos Universitários*\nhttps://app.santanderx.com/calls/santander-x-brazil-award-university-2026?utm_source=Whatsapp&utm_medium=Laminawhats&utm_campaign=SXBR-WhatsappAwardu',0,'chat',1781053943,'2026-06-11T14:52:53.454293',NULL,NULL,NULL,NULL);
