INSERT INTO messages VALUES (56448,'false_120363304055240101@g.us_AC826ECE8CBDE805DBC86168CF349975_20203660402840@lid','120363304055240101@g.us','Montar Times CowwPeões 🐮🫂','20203660402840@lid','Desconhecido','No *Santander X*, também estamos buscando *startups e scaleups* que possuam soluções de *Computação Quântica* para participarem de um desafio global.\n\nSe conhecerem alguém, por favor, indiquem, essa é uma excelente oportunidade de escala global.\n\nA premiação para as vencedoras é: \n\n- *3 startups ganham €10 mil cada* \n- *3 scaleups ganham € 30 mil cada*\n\nAs 6 vencedoras, vão para a Espanha receber a premiação com todas as despesas de aéreo e hospedagem custeados pelo Santander.\n\nhttps://app.santanderx.com/calls/the-quantum-ai-leap?utm_source=whatsapp&utm_medium=social_share&utm_campaign=share_button_preview',0,'chat',1781054191,'2026-06-11T14:52:53.451023',NULL,NULL,NULL,NULL);
