INSERT INTO messages VALUES (56465,'false_120363385874539128@g.us_AC57925EA8691A5CC5CEF3DFFA7D9024_199454019875029@lid','120363385874539128@g.us','Cowwtratação','199454019875029@lid','Desconhecido','Analista de Desenvolvimento de Sistemas - Central Sicredi Centro Norte (Cuiabá/MT)\n\nResponsabilidades e atribuições\n\n* Desenvolver e sustentar aplicações, sistemas e automações, garantindo qualidade funcional e não funcional das soluções.\n* Seguir padrões de arquitetura, infraestrutura, segurança da informação e operação no desenvolvimento de sistemas.\n* Elaborar, atualizar e manter a documentação técnica e funcional dos sistemas desenvolvidos.\n* Executar testes, apoiar correções e atuar na resolução de incidentes e investigação de problemas em sistemas e automações.\n* Apoiar a administração e evolução de ferramentas de automação, integrações e soluções sistêmicas.\n* Atuar em integrações entre diferentes soluções, garantindo simplificação de uso e visão única da informação.\n* Apoiar a implementação de melhorias, mudanças e evoluções nos ambientes, reduzindo riscos operacionais e impactos aos usuários.\n* Interagir com equipes internas e terceiros sempre que necessário para garantir disponibilidade, desempenho e continuidade das soluções.\nhttps://sicredi.gupy.io/jobs/11242742?jobBoardSource=share_link',0,'chat',1781046005,'2026-06-11T14:53:18.696874',NULL,NULL,NULL,NULL);
