INSERT INTO messages VALUES (56462,'false_120363385874539128@g.us_AC53F9FEF7D19C29BBCB31E43F723184_232259147796629@lid','120363385874539128@g.us','Cowwtratação','232259147796629@lid','Desconhecido','💻 #dados \n🧑🏽 #estagio\n🌎 #remoto \n\nEstágio em Ciência de Dados\n\nRequisitos:\n-   Está cursando graduação em Ciência da Computação, Engenharia, Estatística, Matemática ou áreas relacionadas.\n-   Possui base sólida em Estatística e conhecimento em Python.\n-   Tem familiaridade com Git e bibliotecas de dados como pandas e scikit-learn.\n-   Interesse em Deep Learning e serviços em nuvem (AWS) é um diferencial.\n-   Curioso(a), proativo(a) e com pensamento crítico para resolução de problemas.\n-   Boa comunicação e facilidade para trabalho colaborativo.\n-   Possui projetos pessoais, trabalhos acadêmicos, voluntariado ou qualquer experiência prática com LLMs.\n\n🔗 https://job-boards.greenhouse.io/vtex/jobs/6016131004',0,'chat',1781100601,'2026-06-11T14:53:18.684818',NULL,NULL,NULL,NULL);
INSERT INTO messages VALUES (56461,'false_120363385874539128@g.us_ACCC2C42EAE956B87A1ADFB61037966A_232259147796629@lid','120363385874539128@g.us','Cowwtratação','232259147796629@lid','Desconhecido','💻 #dados\n🧑🏽 #estagio\n🌎 #hibrido #SP São Paulo\n\nEstágio em Engenharia de Dados - Synoro Negócios Inovadores\n\nRequisitos:\nObrigatórios:\n- Estar cursando os últimos períodos da graduação ou ser recém-formado(a) em TI, Engenharia, Ciência de Dados, Sistemas de Informação ou áreas correlatas;\n- Interesse genuíno pela área de dados;\n- Curiosidade, proatividade e vontade de aprender;\n- Boa comunicação e organização.\n\nDesejáveis (não obrigatórios):\n- Noções básicas de\xa0programação;\n- Interesse por\xa0computação em nuvem\xa0e seus conceitos gerais;\n- Familiaridade com ideias básicas de\xa0Business Intelligence (BI), como dashboards e indicadores;\n- Compreensão inicial de conceitos de dados (bancos, modelagem, integração etc.).\n\n🔗 https://jobs.compleo.app/gruposynoro/jobdetail/FV98736J',0,'chat',1781101214,'2026-06-11T14:53:18.680999',NULL,NULL,NULL,NULL);
INSERT INTO messages VALUES (56460,'false_120363385874539128@g.us_ACCDC891EF2DECAB80A06356BE1D615D_232259147796629@lid','120363385874539128@g.us','Cowwtratação','232259147796629@lid','Desconhecido','💻  #dev\n🧑🏽 #estagio\n🌎 #presencial #PE Recife\n\nEstagiário em Desenvolvimento - Porto Digital\n\nRequisitos:\n- Conhecimento básico/intermediário em lógica de programação\n- Familiaridade com JavaScript, APIs ou integrações\n- Interesse por automação e ferramentas no-code/low-code\n- Noções de HTML/CSS (para customizações simples)\n- Conhecimento básico em ferramentas de gestão (ex: planilhas, boards, etc.)\n- Não é necessário experiência formal, mas esperamos que já tenha tido algum contato prático com desenvolvimento, automação ou projetos digitais (acadêmicos ou pessoais)\n- Ter explorado ou testado ferramentas digitais além do básico já é um diferencial importante\n- Cursando graduação em áreas como Tecnologia, Sistemas de Informação, Engenharia, ou correlatas\n\n🔗 https://portodigital.vagas.solides.com.br/vaga/854204',0,'chat',1781101257,'2026-06-11T14:53:18.679359',NULL,NULL,NULL,NULL);
INSERT INTO messages VALUES (56459,'false_120363385874539128@g.us_ACBD12ED3DFE302B463F784B04B9E823_232259147796629@lid','120363385874539128@g.us','Cowwtratação','232259147796629@lid','Desconhecido','💻 #segurança \n🧑🏽 #junior \n🌎 #hibrido #PE Recife\n\nAnalista de Segurança da Informação - AVANTIA\n\nRequisitos:\n- Interesse em atuar com Segurança da Informação;\n- Conhecimento básico em redes TCP/IP, VPN e segurança de rede;\n- Conhecimento básico em ambiente Microsoft Windows e Microsoft 365;\n- Noções de Firewall, Active Directory e controle de acessos;\n- Perfil analítico, organizado e com vontade de aprender;\n- Boa comunicação e capacidade de trabalhar em equipe.\n\n🔗 https://avantia.gupy.io/jobs/11277506',0,'chat',1781101280,'2026-06-11T14:53:18.677941',NULL,NULL,NULL,NULL);
