INSERT INTO messages VALUES (56457,'false_120363385874539128@g.us_AC56D9200A420392545A9094ECB87E24_232259147796629@lid','120363385874539128@g.us','Cowwtratação','232259147796629@lid','Desconhecido','💻 #suporte\n🧑🏽 #estagio\n🌎 #remoto\n\nEstágio em Tecnologia e Sistemas\n\nRequisitos:\n-   Estar cursando graduação em áreas como:\n    -   Tecnologia;\n    -   Sistemas de Informação;\n    -   Engenharia de software;\n    -   Análise e desenvolvimento de sistemas;\n    -   Ou áreas correlatas.\n-   Interesse por tecnologia, sistemas e automação de processos.\n-   Conhecimento básico em ferramentas digitais e pacote Office/Google Workspace.\n-   Boa comunicação verbal e escrita.\n-   Organização e atenção aos detalhes.\n-   Facilidade para aprender novas ferramentas e processos.\n-   Perfil proativo e colaborativo.\n\n🔗 https://vermontxcenter.vagas.solides.com.br/vaga/853729',0,'chat',1781104040,'2026-06-11T14:53:18.674621',NULL,NULL,NULL,NULL);
INSERT INTO messages VALUES (56456,'false_120363385874539128@g.us_ACB521D891302A4322828CDF9183AFAD_114478091923622@lid','120363385874539128@g.us','Cowwtratação','114478091923622@lid','Desconhecido','*Oportunidade: Operations Analyst*\n\n🌍 *TRABALHO REMOTO*\n\n🏢 *Vintti:* Empresa que conecta profissionais da América Latina a empresas dos Estados Unidos, atuando principalmente com recrutamento internacional para áreas de operações, tecnologia, finanças e negócios.\n\n💰 Salário: não informado\n💰 Média estimada: R$ 6.000 – R$ 10.000/mês\n\n*Requisitos essenciais:*\n🔹 Experiência em Trading Operations ou Middle Office\n🔹 Experiência prática com liquidação de ativos no mercado americano\n🔹 Conhecimento do ciclo completo de operações financeiras (execução → alocação → clearing → settlement)\n🔹 Excel avançado (tabelas dinâmicas, fórmulas e manipulação de dados)\n🔹 Perfil analítico e atenção aos detalhes\n🔹 Boa comunicação e trabalho em equipe\n🔹 Capacidade de resolver divergências operacionais e financeiras\n\n🔗 Para se candidatar: https://www.linkedin.com/jobs/view/4418208337/\n\n📚 Cursos para se preparar\nCurso de Gerenciamento de Projetos e Processos: https://bit.ly/tetra-gestão-de-projetos\nCurso de Excel avançado: https://bit.ly/tetra-excel-avancado\nCurso de Inteligência Artificial: https://bit.ly/tetra-curso-de-ia',0,'chat',1781116037,'2026-06-11T14:53:18.673291',NULL,NULL,NULL,NULL);
INSERT INTO messages VALUES (56454,'false_120363385874539128@g.us_AC22C09E7F5C93DE21950932D684CA6D_114478091923622@lid','120363385874539128@g.us','Cowwtratação','114478091923622@lid','Desconhecido','*Oportunidade: Desenvolvedor Power BI Pleno*\n\n🌍 *TRABALHO REMOTO*\n\n🏢 *Engineering Brasil:* Empresa de tecnologia e transformação digital que atua com soluções de software, dados, cloud, automação e inovação para grandes empresas no Brasil e no exterior.\n\n💰 Salário: não informado\n💰 Média estimada: R$ 7.000 – R$ 10.000/mês\n\n*Requisitos essenciais:*\n🔹 Formação em Tecnologia, Sistemas de Informação ou Engenharia\n🔹 Experiência sólida com Power BI em projetos corporativos\n🔹 Conhecimento avançado em modelagem dimensional\n🔹 Domínio de DAX, Power Query e SQL\n🔹 Experiência com dashboards executivos e indicadores estratégicos\n🔹 Experiência com integração de dados e múltiplas fontes\n🔹 Perfil analítico e visão de negócio\n🔹 Experiência em levantamento de requisitos funcionais\n\n🔗 Para se candidatar: https://www.linkedin.com/jobs/view/4415240311/\n\n📚 Cursos para se preparar\nCurso de Excel avançado: https://bit.ly/tetra-excel-avancado\nCurso de Power BI avançado: https://bit.ly/tetra-powerbi-avancado\nCurso de Storytelling de dados: https://bit.ly/tetra-dashboard-storytelling',0,'chat',1781116038,'2026-06-11T14:53:18.667918',NULL,NULL,NULL,NULL);
INSERT INTO messages VALUES (56455,'false_120363385874539128@g.us_AC76F9541136C416848BAC221274F5CE_114478091923622@lid','120363385874539128@g.us','Cowwtratação','114478091923622@lid','Desconhecido','*Oportunidade: Analista de Dados Pleno*\n\n🌍 *TRABALHO REMOTO*\n\n🏢 *Clin Digital:* Operadora de planos odontológicos com mais de 370 mil beneficiários, focada em saúde, tecnologia e experiência do cliente, atuando principalmente no Norte e Nordeste do Brasil.\n\n💰 Salário: não informado\n💰 Média estimada: R$ 5.500 – R$ 8.500/mês\n\n*Requisitos essenciais:*\n🔹 Formação em Ciência de Dados, Estatística, Engenharia, Sistemas de Informação, Administração ou áreas correlatas\n🔹 Conhecimento sólido em SQL (joins, subqueries, window functions e CTEs)\n🔹 Experiência com ferramentas de BI e visualização de dados\n🔹 Experiência com Metabase\n🔹 Capacidade analítica para gerar insights estratégicos\n🔹 Boa comunicação com áreas técnicas e de negócio\n\n🔗 Para se candidatar: https://www.linkedin.com/jobs/view/4417662183/\n\n📚 Cursos para se preparar\nCurso de conexão em banco de dados SQL: https://bit.ly/tetra-banco-de-dados-sql\nCurso de Power BI avançado: https://bit.ly/tetra-powerbi-avancado\nCurso de Storytelling de dados: https://bit.ly/tetra-dashboard-storytelling',0,'chat',1781116038,'2026-06-11T14:53:18.670646',NULL,NULL,NULL,NULL);
